export const mealPlanLabel = (code: string | undefined, lang: 'ar' | 'en') => {
  if (!code) return ''
  const plan = mealPlans.find((meal) => meal.code === code)
  return plan ? `${code} · ${lang === 'ar' ? plan.ar : plan.en}` : code
}
